import csv, math, datetime
from collections import defaultdict
p='/archive/payment_batch_export_X4oS5LQndz.tsv'
rows=[]
with open(p,newline='',encoding='utf-8') as f:
    r=csv.DictReader(f,delimiter='\t')
    for row in r:
        row['amount_cents']=int(row['amount_cents'])
        row['lat']=float(row['observed_lat'])
        row['lon']=float(row['observed_lon'])
        row['dt']=datetime.datetime.fromisoformat(row['created_at'].replace('Z','+00:00'))
        rows.append(row)

fraud=set()
# pattern a: payment method shared across customers
pm_cust=defaultdict(set)
for x in rows: pm_cust[x['payment_method_fingerprint']].add(x['customer_ref'])
shared_pm={k for k,v in pm_cust.items() if len(v)>=2}
for x in rows:
    if x['payment_method_fingerprint'] in shared_pm: fraud.add(x['row_id'])

# pattern b: device shared across customers
dev_cust=defaultdict(set)
for x in rows: dev_cust[x['device_fingerprint']].add(x['customer_ref'])
shared_dev={k for k,v in dev_cust.items() if len(v)>=2}
for x in rows:
    if x['device_fingerprint'] in shared_dev: fraud.add(x['row_id'])

# pattern d: same customer rapid different stores with large geo gap within 30m (using observed coords)
by_c=defaultdict(list)
for x in rows: by_c[x['customer_ref']].append(x)
for c,arr in by_c.items():
    arr=sorted(arr,key=lambda z:z['dt'])
    for i in range(len(arr)-1):
        a,b=arr[i],arr[i+1]
        dt=(b['dt']-a['dt']).total_seconds()/60
        if dt<30 and a['store_ref']!=b['store_ref']:
            d=((a['lat']-b['lat'])**2+(a['lon']-b['lon'])**2)**0.5
            if d>1.0:
                fraud.add(a['row_id']); fraud.add(b['row_id'])

# pattern g: same rounded coords across >=3 customers
coord_c=defaultdict(set)
for x in rows:
    key=(round(x['lat'],4),round(x['lon'],4))
    coord_c[key].add(x['customer_ref'])
coord_bad={k for k,v in coord_c.items() if len(v)>=3}
for x in rows:
    if (round(x['lat'],4),round(x['lon'],4)) in coord_bad:
        fraud.add(x['row_id'])

fraud_rows=[x for x in rows if x['row_id'] in fraud]
print('fraud_count',len(fraud_rows))
print('fraud_ids',','.join(x['row_id'] for x in fraud_rows))
print('sum_cents',sum(x['amount_cents'] for x in fraud_rows))

# also print non-trivial candidate: high-value Makita workshop bursts (>=200000)
hi=[x for x in rows if x['amount_cents']>=200000]
print('hi',[(x['row_id'],x['customer_ref'],x['amount_cents']) for x in hi])
